package httpserver

import (
	"io"
	"net/http"
)

func renderPartyDirectory(w http.ResponseWriter) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = io.WriteString(w, partyDemoPage)
}

func partyDemoScript(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
	_, _ = io.WriteString(w, partyDemoJavaScript)
}

const partyDemoPage = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>主体目录</title><style>` + partyDemoCSS + `</style></head><body>
<header class="top"><a class="brand" href="./"><span>PD</span><strong>主体目录</strong></a><div class="session"><span id="credentialState">尚未连接</span><button id="refreshPermissions" class="quiet">刷新权限</button><button id="openCredential" class="quiet">设置访问凭证</button><a href="../workbench/">统一工作台</a></div></header>
<div class="shell"><aside class="rail"><p class="eyebrow">Party Directory</p><button class="nav active">主体档案</button><div class="rail-note"><strong>一个稳定身份，多处业务引用</strong><span>这里管理当前档案；合同、资金和项目继续拥有各自角色与历史快照。</span></div></aside>
<main><section class="page-head"><div><p class="eyebrow">主体档案</p><h1>组织与个人主体</h1><p>登记、查找和维护稳定 Party ID。名称变化会留下 revision，不会改写已经发生的业务。</p></div><button id="newParty" class="primary" hidden>登记主体</button></section>
<div id="notice" class="notice">请从统一工作台进入，或在独立模式设置模板凭证。</div>
<aside id="accessRecovery" class="recovery" hidden><div><strong>当前权限不可用</strong><span>页面已退出编辑状态。刷新权限后重试；撤权后不会继续显示旧动作。</span></div><a href="../workbench/">返回工作台</a></aside>
<section class="filters"><label>搜索名称或登记标识<input id="query" placeholder="例如：示范设计院"></label><label>类型<select id="kind"><option value="">全部类型</option><option value="organization">组织</option><option value="individual">个人</option></select></label><label>状态<select id="status"><option value="active">启用</option><option value="inactive">停用</option><option value="all">全部</option></select></label><button id="search" class="quiet">查询</button></section>
<div class="workspace"><section class="list-region"><div class="section-title"><div><h2>主体列表</h2><span id="count">0 条</span></div><button id="reload" class="quiet">刷新</button></div><div id="partyList" class="records"><div class="empty"><strong>尚未读取主体</strong><span>连接后显示当前租户的主体档案。</span></div></div></section>
<section class="detail-region"><div id="detailEmpty" class="empty large"><strong>选择一个主体</strong><span>查看当前档案、稳定 ID、可用动作与不可变 revision 历史。</span></div><div id="detail" hidden><div class="detail-head"><div><div class="badges"><span id="detailKind" class="badge"></span><span id="detailStatus" class="badge"></span></div><h2 id="detailName"></h2><code id="detailID"></code></div><button id="reloadDetail" class="quiet">重新载入</button></div><dl class="facts"><div><dt>当前 revision</dt><dd id="detailRevision"></dd></div><div><dt>登记标识</dt><dd id="detailRegistration"></dd></div><div><dt>更新时间</dt><dd id="detailUpdated"></dd></div></dl><div id="actionChips" class="chips"></div>
<div class="tabs"><button class="tab active" data-pane="profile">当前档案</button><button class="tab" data-pane="history">修订历史</button></div>
<section id="profile" class="pane active"><form id="updateForm" class="form"><div class="two"><label>主体类型<select name="kind"><option value="organization">组织</option><option value="individual">个人</option></select></label><label>登记标识<input name="registration_identifier" maxlength="100"></label></div><label>法定名称／姓名<input name="legal_name" maxlength="200" required></label><label>更正原因<textarea name="reason" rows="3" required placeholder="说明本次更正的业务原因"></textarea></label><button class="primary" type="submit">保存更正</button></form><p id="updateDenied" class="permission" hidden>当前权限只能查看档案，不能更正资料。</p>
<div id="statusAction" class="status-action"><div><strong id="statusTitle"></strong><span id="statusHelp"></span></div><button id="changeStatus" class="danger"></button></div></section>
<section id="history" class="pane"><div class="section-title"><h3>不可变 revision</h3><button id="loadHistory" class="quiet">读取历史</button></div><div id="historyList" class="timeline"><div class="empty">打开历史后显示每次变化、原因与可信 Actor。</div></div><p id="historyDenied" class="permission" hidden>当前凭证没有读取历史的能力。</p></section></div></section></div></main></div>
<dialog id="credentialDialog"><form id="credentialForm" method="dialog"><p class="eyebrow">独立模式</p><h2>设置模板访问凭证</h2><p>正式组合由 Gateway 使用 IAM 会话换取短期凭证。这里的 Token 只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">保存并连接</button></div></form></dialog>
<dialog id="createDialog"><form id="createForm" method="dialog"><p class="eyebrow">登记主体</p><h2>建立稳定 Party ID</h2><p>客户、供应商或甲方等业务角色不在这里固化；消费应用在自己的业务上下文中保存角色。</p><label>主体类型<select name="kind"><option value="organization">组织</option><option value="individual">个人</option></select></label><label>法定名称／姓名<input name="legal_name" maxlength="200" required></label><label>登记标识（可选）<input name="registration_identifier" maxlength="100"></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="primary">登记主体</button></div></form></dialog>
<dialog id="statusDialog"><form id="statusForm" method="dialog"><p class="eyebrow">状态变化</p><h2 id="statusDialogTitle"></h2><p id="statusDialogHelp"></p><label>原因<textarea name="reason" rows="3" required></textarea></label><div class="dialog-actions"><button value="cancel" class="quiet">取消</button><button value="default" class="danger">确认状态变化</button></div></form></dialog>
<script src="assets/demo.js"></script></body></html>`

const partyDemoCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,sans-serif;color:#18212f;background:#f7f8fa;line-height:1.55;--ink:#18212f;--muted:#566273;--line:#e2e6eb;--strong:#b9c1cc;--accent:#3157a4;--accent-soft:#edf2fb;--danger:#a93a33;--warning:#8a5a00;--success:#26734d}*{box-sizing:border-box}body{margin:0}.top{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:4}.brand,.session{display:flex;align-items:center;gap:11px}.brand{color:var(--ink);text-decoration:none}.brand span{display:grid;place-items:center;width:34px;height:34px;border-radius:6px;background:#203c75;color:#fff;font-size:12px;font-weight:800}.session{color:var(--muted);font-size:12px}.session a{color:var(--accent);font-weight:700}.shell{display:grid;grid-template-columns:224px minmax(0,1fr);min-height:calc(100vh - 58px)}.rail{padding:28px 18px;background:#fff;border-right:1px solid var(--line)}.eyebrow{margin:0 0 8px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{width:100%;padding:11px 13px;border:0;border-left:3px solid var(--accent);background:var(--accent-soft);color:var(--accent);text-align:left;font:inherit;font-weight:750}.rail-note{display:grid;gap:6px;margin-top:30px;padding:18px 12px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.rail-note strong{color:var(--ink)}main{min-width:0;padding:32px;max-width:1500px}.page-head,.section-title,.detail-head,.status-action{display:flex;align-items:center;justify-content:space-between;gap:18px}.page-head{margin-bottom:20px}.page-head h1{margin:0 0 5px;font-size:28px}.page-head p:not(.eyebrow){max-width:720px;margin:0;color:var(--muted)}h2,h3,p{margin-top:0}.primary,.quiet,.danger{min-height:38px;padding:8px 14px;border:1px solid transparent;border-radius:7px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.quiet{border-color:var(--strong);background:#fff;color:#384354}.danger{background:var(--danger);color:#fff}.primary:focus-visible,.quiet:focus-visible,.danger:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,.record:focus-visible,.tab:focus-visible{outline:2px solid #2f6fdb;outline-offset:2px}.notice,.recovery{margin-bottom:16px;padding:12px 14px;border:1px solid #cad7ea;border-radius:7px;background:#f2f6fc;color:#315477;font-size:13px}.notice.ok{border-color:#bedbc9;background:#f0f8f3;color:var(--success)}.notice.error{border-color:#e5bdb9;background:#fff3f2;color:var(--danger)}.recovery{display:flex;justify-content:space-between;background:#fff8e8;border-color:#e7c17c}.recovery div{display:grid;gap:3px}.recovery span{color:#725626}.recovery a{align-self:center;color:var(--accent);font-weight:700}.filters{display:grid;grid-template-columns:minmax(260px,1fr) 170px 150px auto;align-items:end;gap:12px;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}label{display:grid;gap:6px;color:#465163;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:9px 10px;border:1px solid var(--strong);border-radius:6px;background:#fff;color:var(--ink);font:inherit;font-size:13px}.workspace{display:grid;grid-template-columns:390px minmax(0,1fr);gap:28px;padding-top:24px}.list-region{border-right:1px solid var(--line);padding-right:28px}.section-title h2,.section-title h3{margin:0}.section-title span{color:var(--muted);font-size:12px}.records{display:grid;gap:2px;margin-top:12px}.record{display:grid;grid-template-columns:1fr auto;gap:3px 12px;width:100%;padding:14px 12px;border:0;border-bottom:1px solid var(--line);background:transparent;color:var(--ink);text-align:left;cursor:pointer}.record:hover,.record.active{background:#eef1f4}.record strong{font-size:15px}.record small{color:var(--muted)}.record .record-status{grid-row:1/3;grid-column:2;color:var(--muted);font-size:11px}.empty{display:grid;gap:6px;padding:32px;color:var(--muted);font-size:13px;text-align:center}.empty.large{min-height:460px;place-content:center}.detail-region{min-width:0}.detail-head{padding-bottom:18px;border-bottom:1px solid var(--line)}.detail-head h2{margin:6px 0 3px;font-size:24px}.detail-head code{color:var(--muted);font-size:11px}.badges,.chips{display:flex;flex-wrap:wrap;gap:6px}.badge,.chip{padding:3px 8px;border:1px solid #ccd4e0;border-radius:999px;background:#f5f7fa;color:#465163;font-size:11px}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;margin:18px 0;background:var(--line)}.facts div{padding:14px;background:#fff}.facts dt{color:var(--muted);font-size:11px}.facts dd{margin:4px 0 0;font-size:14px}.tabs{display:flex;margin-top:20px;border-bottom:1px solid var(--line)}.tab{padding:11px 14px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);font:inherit;cursor:pointer}.tab.active{border-color:var(--accent);color:var(--accent);font-weight:750}.pane{display:none;padding-top:20px}.pane.active{display:block}.form{display:grid;gap:12px;max-width:720px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.permission{padding:12px;background:#eef1f4;color:var(--muted);font-size:13px}.status-action{max-width:720px;margin-top:24px;padding-top:18px;border-top:1px solid var(--line)}.status-action div{display:grid;gap:3px}.status-action span{color:var(--muted);font-size:12px}.timeline{display:grid;gap:10px;margin-top:14px}.event{padding:12px 14px;border-left:3px solid #9aa8bc;background:#f7f8fa}.event strong{display:block}.event span{color:var(--muted);font-size:12px}dialog{width:min(560px,calc(100% - 32px));padding:26px;border:1px solid var(--line);border-radius:10px;box-shadow:0 12px 28px #18212f29}dialog::backdrop{background:#18212f99}dialog p{color:var(--muted);font-size:13px}.dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:18px}@media(max-width:980px){.shell{grid-template-columns:1fr}.rail{display:none}.workspace{grid-template-columns:1fr}.list-region{border-right:0;border-bottom:1px solid var(--line);padding:0 0 20px}.filters{grid-template-columns:1fr 1fr}}@media(max-width:640px){.top{height:auto;min-height:58px;padding:10px 15px}.session{flex-wrap:wrap;justify-content:flex-end}.session>span{display:none}main{padding:20px}.page-head,.status-action{align-items:flex-start;flex-direction:column}.filters,.two,.facts{grid-template-columns:1fr}}`

const partyDemoJavaScript = `(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],suiteBase=location.pathname==='/'?'':location.pathname.replace(/\/$/,''),state={token:sessionStorage.getItem('party-demo-token')||'',items:[],listActions:[],selected:null};
const A={read:'read',update:'update',status:'status_manage',history:'history_read',create:'party-directory.create'},uuid=()=>crypto.randomUUID(),fmt=v=>v?new Date(v).toLocaleString('zh-CN'):'—';
function notice(message,type=''){const n=$('#notice');n.textContent=message;n.className='notice '+type}
function problem(response,data){const e=new Error(data.detail||data.error?.message||('请求失败 '+response.status));e.status=response.status;e.code=data.code||data.error?.code||'';e.data=data;return e}
async function api(path,opt={}){const headers={...(opt.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;if(opt.body&&!headers['Content-Type'])headers['Content-Type']='application/json';const r=await fetch(suiteBase+path,{credentials:'same-origin',...opt,headers});const text=await r.text();let data={};try{data=text?JSON.parse(text):{}}catch{const e=new Error(r.redirected?'需要从统一工作台重新进入应用':'服务返回了无法识别的内容');e.status=r.status;throw e}if(!r.ok)throw problem(r,data);return data}
function connected(){return !!suiteBase||!!state.token}
function recover(error){if(error.status===401||error.status===403){$('#accessRecovery').hidden=false;$('#newParty').hidden=true}notice(error.message||'请求失败','error')}
function renderList(){const root=$('#partyList');root.replaceChildren();$('#count').textContent=state.items.length+' 条';$('#newParty').hidden=!state.listActions.includes(A.create);if(!state.items.length){const e=document.createElement('div');e.className='empty';e.innerHTML='<strong>没有符合条件的主体</strong><span>'+(state.listActions.includes(A.create)?'可以登记第一条主体档案，或调整筛选。':'当前权限范围没有可查看记录。')+'</span>';root.append(e);return}state.items.forEach(item=>{const b=document.createElement('button');b.className='record'+(state.selected?.id===item.id?' active':'');b.innerHTML='<strong></strong><small></small><span class="record-status"></span>';b.querySelector('strong').textContent=item.legal_name;b.querySelector('small').textContent=(item.kind==='organization'?'组织':'个人')+' · revision '+item.revision;b.querySelector('.record-status').textContent=item.status==='active'?'启用':'停用';b.onclick=()=>openParty(item.id);root.append(b)})}
async function loadParties(){try{notice('正在读取主体目录与当前权限…');const q=new URLSearchParams({status:$('#status').value,limit:'100'});if($('#query').value.trim())q.set('query',$('#query').value.trim());if($('#kind').value)q.set('kind',$('#kind').value);const page=await api('/api/v1/parties?'+q);state.items=page.items||[];state.listActions=page.allowed_actions||[];renderList();$('#accessRecovery').hidden=true;notice('主体目录已同步。','ok')}catch(e){state.items=[];renderList();recover(e)}}
function showPane(id){$$('.pane').forEach(x=>x.classList.toggle('active',x.id===id));$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.pane===id))}
function renderDetail(){const p=state.selected;if(!p){$('#detail').hidden=true;$('#detailEmpty').hidden=false;return}$('#detail').hidden=false;$('#detailEmpty').hidden=true;$('#detailKind').textContent=p.kind==='organization'?'组织':'个人';$('#detailStatus').textContent=p.status==='active'?'启用':'停用';$('#detailName').textContent=p.legal_name;$('#detailID').textContent=p.id;$('#detailRevision').textContent=p.revision;$('#detailRegistration').textContent=p.registration_identifier||'未填写';$('#detailUpdated').textContent=fmt(p.updated_at);const actions=p.allowed_actions||[],chips=$('#actionChips');chips.replaceChildren();actions.forEach(x=>{const s=document.createElement('span');s.className='chip';s.textContent=x;chips.append(s)});const f=$('#updateForm');f.elements.kind.value=p.kind;f.elements.legal_name.value=p.legal_name;f.elements.registration_identifier.value=p.registration_identifier||'';f.elements.reason.value='';f.hidden=!actions.includes(A.update);$('#updateDenied').hidden=actions.includes(A.update);$('#statusAction').hidden=!actions.includes(A.status);const inactive=p.status==='inactive';$('#statusTitle').textContent=inactive?'重新启用主体':'停用主体';$('#statusHelp').textContent=inactive?'恢复后可以形成新的业务引用；旧快照不变化。':'停用后不能形成新的业务引用；既有历史仍可读。';$('#changeStatus').textContent=inactive?'重新启用':'停用';$('#changeStatus').className=inactive?'primary':'danger';$('#historyDenied').hidden=actions.includes(A.history);renderList()}
async function openParty(id){try{notice('正在读取主体当前档案…');state.selected=await api('/api/v1/parties/'+id);renderDetail();showPane('profile');notice('已加载当前 revision '+state.selected.revision+'。','ok')}catch(e){recover(e)}}
async function loadHistory(){if(!state.selected)return;try{const data=await api('/api/v1/parties/'+state.selected.id+'/history?limit=100'),root=$('#historyList');root.replaceChildren();(data.items||[]).forEach(x=>{const e=document.createElement('div');e.className='event';e.innerHTML='<strong></strong><span></span>';e.querySelector('strong').textContent='revision '+x.revision+' · '+x.event_kind+' · '+x.legal_name;e.querySelector('span').textContent=fmt(x.occurred_at)+' · '+(x.reason||'首次登记')+' · Actor '+x.actor_ref;root.append(e)});if(!root.children.length)root.textContent='暂无历史。';showPane('history')}catch(e){recover(e)}}
function compact(value){const v=String(value||'').trim();return v||null}
function setCredentialState(){const suite=!!suiteBase,ok=connected();$('#credentialState').textContent=suite?'Gateway / IAM 短期能力凭证':ok?'本地模板凭证已连接':'尚未连接';$('#openCredential').hidden=suite;$('#refreshPermissions').hidden=!ok;if(ok)loadParties()}
function cookie(name){return document.cookie.split(';').map(x=>x.trim()).find(x=>x.startsWith(name+'='))?.slice(name.length+1)||''}
async function refreshPermissions(){try{if(!suiteBase){await loadParties();if(state.selected)await openParty(state.selected.id);return}notice('正在从 IAM 刷新主体目录权限…');const csrf=decodeURIComponent(cookie('oms_iam_csrf'));if(!csrf)throw new Error('缺少统一入口安全令牌，请返回工作台重新进入');const body=new URLSearchParams({csrf_token:csrf});const response=await fetch('/gateway/authorize/party-directory',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded','X-CSRF-Token':csrf},body,redirect:'follow'});if(!response.ok){let data={};try{data=await response.json()}catch{}throw problem(response,data)}await loadParties();if(state.selected)await openParty(state.selected.id);$('#accessRecovery').hidden=true}catch(e){recover(e)}}
$$('.tab').forEach(x=>x.onclick=()=>showPane(x.dataset.pane));$('#search').onclick=loadParties;$('#reload').onclick=loadParties;$('#reloadDetail').onclick=()=>state.selected&&openParty(state.selected.id);$('#refreshPermissions').onclick=refreshPermissions;$('#newParty').onclick=()=>$('#createDialog').showModal();
$('#openCredential').onclick=()=>{$('#token').value=state.token;$('#credentialDialog').showModal()};$('#credentialForm').onsubmit=e=>{e.preventDefault();state.token=$('#token').value.trim();sessionStorage.setItem('party-demo-token',state.token);$('#credentialDialog').close();setCredentialState()};
$('#createForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const p=await api('/api/v1/parties',{method:'POST',body:JSON.stringify({command_id:uuid(),kind:f.get('kind'),legal_name:f.get('legal_name'),registration_identifier:compact(f.get('registration_identifier'))})});$('#createDialog').close();e.target.reset();await loadParties();await openParty(p.id);notice('主体已登记，revision 1。','ok')}catch(err){recover(err)}};
$('#updateForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),draft={kind:f.get('kind'),legal_name:f.get('legal_name'),registration_identifier:f.get('registration_identifier'),reason:f.get('reason')},p=state.selected;try{await api('/api/v1/parties/'+p.id,{method:'PUT',body:JSON.stringify({command_id:uuid(),expected_revision:p.revision,kind:draft.kind,legal_name:draft.legal_name,registration_identifier:compact(draft.registration_identifier),reason:draft.reason})});await loadParties();await openParty(p.id);notice('档案已更正并追加新的 revision。','ok')}catch(err){if(err.status===409&&err.code==='PARTY_REVISION_CONFLICT'){await openParty(p.id);Object.entries(draft).forEach(([k,v])=>{if(e.target.elements[k])e.target.elements[k].value=v});notice('发生 revision 冲突：已加载最新事实并保留你的输入，请核对后重新提交。','error')}else recover(err)}};
$('#changeStatus').onclick=()=>{const inactive=state.selected.status==='inactive';$('#statusDialogTitle').textContent=inactive?'重新启用该主体':'停用该主体';$('#statusDialogHelp').textContent=inactive?'恢复新业务引用资格，不改写任何旧快照。':'阻止新的业务引用，现有合同、资金和项目快照保持不变。';$('#statusDialog').showModal()};
$('#statusForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),p=state.selected,target=p.status==='active'?'inactive':'active';try{await api('/api/v1/parties/'+p.id+'/status-changes',{method:'POST',body:JSON.stringify({command_id:uuid(),expected_revision:p.revision,status:target,reason:f.get('reason')})});$('#statusDialog').close();e.target.reset();await loadParties();await openParty(p.id);notice(target==='active'?'主体已重新启用。':'主体已停用；既有快照仍可解释。','ok')}catch(err){recover(err)}};
$('#loadHistory').onclick=loadHistory;setCredentialState();})();`
